#requires -Version 7.0
<#
.SYNOPSIS
Builds the specifically user-approved official Lua 5.1.5 archive using installed MSVC.
.NOTES
No download/update or PATH change. Verifies pinned archive SHA256; creates only a new destination.
#>
[CmdletBinding()]
param([string]$Destination=(Join-Path $PSScriptRoot 'bin'),[string]$VcVarsPath='C:\Program Files (x86)\Microsoft Visual Studio\2022\BuildTools\VC\Auxiliary\Build\vcvars64.bat',[string]$WindowsSdkRoot='C:\Program Files (x86)\Windows Kits\10',[ValidatePattern('^\d+\.\d+\.\d+\.\d+$')][string]$WindowsSdkVersion='10.0.26100.0',[switch]$Json)
$ErrorActionPreference='Stop';$tool=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent;. (Join-Path $tool 'lib\PlatformResources.ps1');$r=New-PlatformResult 'Build-Lua' 'ApprovedLua515Build';$global:LASTEXITCODE=125
try{
 $archive=Assert-PlatformPath (Join-Path $PSScriptRoot 'lua-5.1.5.tar.gz');$expected='2640fc56a795f29d28ef15e13c34a47e223960b0240e8cb0a82d9b0738695333';if((Get-FileHash -LiteralPath $archive).Hash.ToLowerInvariant() -cne $expected){throw 'Official source archive checksum mismatch.'};$dest=Assert-PlatformPath $Destination -New;$vcvars=Assert-PlatformPath $VcVarsPath;if(-not(Test-Path -LiteralPath $vcvars -PathType Leaf)){throw 'Verified MSVC environment initializer missing.'};foreach($p in @($dest,$vcvars)){if($p -match '[&|<>^%!"\x00-\x1f]'){throw 'Build paths contain unsupported cmd metacharacters.'}}
 function Read-Archive([switch]$Extract){$fs=[IO.File]::OpenRead($archive);$gz=[IO.Compression.GZipStream]::new($fs,[IO.Compression.CompressionMode]::Decompress);$reader=[System.Formats.Tar.TarReader]::new($gz);$count=0;$total=0L;try{while($entry=$reader.GetNextEntry()){$name=$entry.Name;if(++$count -gt 1000 -or $name.Length -gt 300 -or -not $name.StartsWith('lua-5.1.5/',[StringComparison]::Ordinal) -or [IO.Path]::IsPathRooted($name) -or $name -match '[:\\\x00-\x1f]' -or @($name.TrimEnd('/').Split('/')|Where-Object{$_ -in @('','..','.')}).Count){throw 'Unsafe tar archive path/count.'};if($entry.EntryType -notin @([System.Formats.Tar.TarEntryType]::RegularFile,[System.Formats.Tar.TarEntryType]::V7RegularFile,[System.Formats.Tar.TarEntryType]::Directory)){throw 'Only regular files/directories accepted; archive links refused.'};if($entry.Length -gt 1048576 -or ($total+=$entry.Length) -gt 8388608){throw 'Tar extraction size limit.'};if($Extract){$target=Join-Path $dest ('source/'+$name);if($entry.EntryType -eq [System.Formats.Tar.TarEntryType]::Directory){$null=[IO.Directory]::CreateDirectory($target)}else{$null=[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target));$stream=[IO.File]::Open($target,[IO.FileMode]::CreateNew);try{$entry.DataStream.CopyTo($stream)}finally{$stream.Dispose()}}}}}finally{$reader.Dispose();$gz.Dispose();$fs.Dispose()}}
 $sdk=Assert-PlatformPath $WindowsSdkRoot;if($sdk -match '[&|<>^%!"\x00-\x1f]'){throw 'SDK path has unsupported cmd metacharacters.'};$include=@(foreach($part in @('ucrt','shared','um')){Join-Path $sdk "Include\$WindowsSdkVersion\$part"});$libs=@(foreach($part in @('ucrt','um')){Join-Path $sdk "Lib\$WindowsSdkVersion\$part\x64"});foreach($p in $include+$libs){if(-not(Test-Path -LiteralPath (Assert-PlatformPath $p) -PathType Container)){throw 'Selected Windows SDK include/library directory missing.'}}
 Read-Archive;$null=[IO.Directory]::CreateDirectory($dest);Read-Archive -Extract;$src=Join-Path $dest 'source\lua-5.1.5\src';$sources=@(Get-ChildItem -LiteralPath $src -Filter '*.c' -File|Sort-Object Name);$core=@($sources|Where-Object{$_.Name -notin @('lua.c','luac.c','print.c')});$lines=[Collections.Generic.List[string]]::new();$lines.Add('@echo off');$lines.Add('call "'+$vcvars+'" >nul');$lines.Add('if errorlevel 1 exit /b %errorlevel%')
 foreach($name in @('lua','luac')){$obj=Join-Path $dest ($name+'-obj');$null=[IO.Directory]::CreateDirectory($obj);$selectedNames=if($name -eq 'lua'){@('lua.c')}else{@('luac.c','print.c')};$units=$core+@($sources|Where-Object{$_.Name -in $selectedNames});$lines.Add('pushd "'+$obj+'"');$line='cl.exe /nologo /O2 /DLUA_USE_WINDOWS /D_CRT_SECURE_NO_WARNINGS /I"'+$src+'" '+(@($include|ForEach-Object{'/I"'+$_+'"'}) -join ' ')+' /Fe:"'+(Join-Path $dest ($name+'.exe'))+'" '+(@($units|ForEach-Object{'"'+$_.FullName+'"'}) -join ' ')+' /link /INCREMENTAL:NO '+(@($libs|ForEach-Object{'/LIBPATH:"'+$_+'"'}) -join ' ');$lines.Add($line);$lines.Add('if errorlevel 1 exit /b %errorlevel%');$lines.Add('popd')};$lines.Add('exit /b 0');$lines|Set-Content -LiteralPath (Join-Path $dest 'build.cmd') -Encoding ascii
 if(-not ('LocalDevTools.PlatformProcess' -as [type])){Add-Type -Path (Join-Path $tool 'lib\PlatformResources.cs')};$cmd=[LocalDevTools.PlatformProcess]::Run((Resolve-PlatformExe 'cmd.exe'),@('/d','/c','build.cmd'),$dest,120,2097152);[IO.File]::WriteAllBytes((Join-Path $dest 'build.stdout.log'),$cmd.Output);[IO.File]::WriteAllText((Join-Path $dest 'build.stderr.log'),$cmd.Error);$r.buildExitCode=$cmd.ExitCode;if($cmd.ExitCode -ne 0 -or $cmd.TimedOut -or $cmd.Truncated){$global:LASTEXITCODE=2;throw 'Lua build failed; inspect retained stdout/stderr logs.'}
 $version=Invoke-PlatformCommand (Join-Path $dest 'lua.exe') @('-v') 10;$text=[Text.Encoding]::UTF8.GetString($version.Output)+$version.Error;if($version.ExitCode -ne 0 -or $text -notmatch 'Lua 5\.1\.5'){$global:LASTEXITCODE=2;throw 'Built interpreter version probe failed.'};[IO.File]::Copy((Join-Path $dest 'source\lua-5.1.5\COPYRIGHT'),(Join-Path $dest 'COPYRIGHT'),$false)
 $r.sourceUrl='https://www.lua.org/ftp/lua-5.1.5.tar.gz';$r.sourceSha256=$expected;$r.compilerEnvironment=$vcvars;$r.flags=@('/O2','/DLUA_USE_WINDOWS','/D_CRT_SECURE_NO_WARNINGS','normal configured CRT');$r.version=$text.Trim();$r.destination=$dest;$r.artifacts=@(foreach($name in @('lua.exe','luac.exe')){@{path=(Join-Path $dest $name);sha256=(Get-FileHash -LiteralPath (Join-Path $dest $name)).Hash}});$r.license='MIT; exact upstream COPYRIGHT retained';$r.valid=$true;$global:LASTEXITCODE=0;$r|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $dest 'build-provenance.json')
}catch{$r.error=$_.Exception.Message};Write-PlatformResult $r -Json:$Json
